# Coroutines Reference

## Structured Concurrency Fundamentals

Every coroutine must be launched in a `CoroutineScope` that defines its lifetime. When the scope is cancelled, all child coroutines are cancelled.

### Scope Hierarchy

```kotlin
// viewModelScope (Android) -- cancelled when ViewModel is cleared
class OrderViewModel : ViewModel() {
    fun loadOrders() {
        viewModelScope.launch {
            val orders = repository.fetchOrders()
            _state.value = orders
        }
    }
}

// lifecycleScope (Android) -- cancelled when lifecycle is destroyed
class OrderFragment : Fragment() {
    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        viewLifecycleOwner.lifecycleScope.launch {
            viewModel.state.collect { state -> render(state) }
        }
    }
}

// Custom scope for server-side components
class OrderProcessor : AutoCloseable {
    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.Default)

    fun processAsync(order: Order) {
        scope.launch { process(order) }
    }

    override fun close() {
        scope.cancel() // Cancels all child coroutines
    }
}
```

### coroutineScope vs supervisorScope

```kotlin
// coroutineScope: child failure cancels ALL siblings
suspend fun fetchAllOrFail(): Pair<User, List<Order>> = coroutineScope {
    val user = async { userService.getUser(userId) }
    val orders = async { orderService.getOrders(userId) }
    // If either fails, both are cancelled
    user.await() to orders.await()
}

// supervisorScope: child failure does NOT cancel siblings
suspend fun fetchWithPartialResults(): UserProfile = supervisorScope {
    val user = async { userService.getUser(userId) }
    val orders = async {
        try { orderService.getOrders(userId) }
        catch (e: Exception) { emptyList() }  // Graceful degradation
    }
    val prefs = async {
        try { prefsService.getPrefs(userId) }
        catch (e: Exception) { Preferences.defaults() }
    }
    UserProfile(user.await(), orders.await(), prefs.await())
}
```

## Dispatcher Selection

```kotlin
// Dispatchers.Main -- UI thread (Android/Compose Desktop)
withContext(Dispatchers.Main) {
    textView.text = "Updated"
}

// Dispatchers.IO -- blocking I/O (network, disk, JDBC)
// Backed by a thread pool that grows up to 64 threads
withContext(Dispatchers.IO) {
    val data = File("data.json").readText()
    database.query("SELECT * FROM users")
}

// Dispatchers.Default -- CPU-intensive work
// Thread count = number of CPU cores
withContext(Dispatchers.Default) {
    val sorted = largeList.sortedBy { it.score }
    val compressed = compress(payload)
}

// limitedParallelism -- constrained concurrency
val dbDispatcher = Dispatchers.IO.limitedParallelism(10)  // Max 10 DB connections
withContext(dbDispatcher) {
    database.query(sql)
}

// Dispatchers.Unconfined -- resumes in caller's thread (testing only)
// Do not use in production code
```

## Cancellation

### Cooperative Cancellation

```kotlin
// Coroutines are cancelled cooperatively -- they must check for cancellation
suspend fun processItems(items: List<Item>) {
    for (item in items) {
        ensureActive()  // Throws CancellationException if cancelled
        process(item)
    }
}

// Alternative: check isActive
suspend fun processItems(items: List<Item>) = coroutineScope {
    for (item in items) {
        if (!isActive) break
        process(item)
    }
}
```

### Timeout

```kotlin
// withTimeout: throws TimeoutCancellationException
val result = withTimeout(5_000) {
    fetchDataFromApi()
}

// withTimeoutOrNull: returns null instead of throwing
val result = withTimeoutOrNull(5_000) {
    fetchDataFromApi()
} ?: defaultValue
```

### Cleanup in Finally

```kotlin
suspend fun processWithCleanup() {
    val resource = acquireResource()
    try {
        // ... work ...
    } finally {
        // Cleanup must complete even if the coroutine is cancelled
        withContext(NonCancellable) {
            resource.release()  // This runs even during cancellation
        }
    }
}
```

### Never Catch CancellationException

```kotlin
// BAD: swallows cancellation
try {
    fetchData()
} catch (e: Exception) {
    log.error("Failed", e)  // CancellationException is caught here!
    return default
}

// GOOD: rethrow CancellationException
try {
    fetchData()
} catch (e: CancellationException) {
    throw e  // Let cancellation propagate
} catch (e: Exception) {
    log.error("Failed", e)
    return default
}

// GOOD: use runCatching carefully
val result = runCatching { fetchData() }
    .onFailure { if (it is CancellationException) throw it }
    .getOrDefault(default)
```

## Concurrency Patterns

### Parallel Map with Limited Concurrency

```kotlin
suspend fun <T, R> Iterable<T>.parallelMap(
    concurrency: Int = 10,
    transform: suspend (T) -> R,
): List<R> = coroutineScope {
    val semaphore = Semaphore(concurrency)
    map { item ->
        async {
            semaphore.withPermit {
                transform(item)
            }
        }
    }.awaitAll()
}

// Usage
val results = urls.parallelMap(concurrency = 5) { url ->
    httpClient.get(url).body<Response>()
}
```

### Fan-Out / Fan-In with Channels

```kotlin
suspend fun processWithWorkers(items: List<Item>, workerCount: Int = 4) = coroutineScope {
    val channel = Channel<Item>(capacity = Channel.BUFFERED)

    // Fan-out: distribute items to workers
    launch {
        for (item in items) { channel.send(item) }
        channel.close()
    }

    // Fan-in: collect results from workers
    val results = (1..workerCount).map {
        async {
            buildList {
                for (item in channel) {
                    add(processItem(item))
                }
            }
        }
    }.awaitAll().flatten()

    results
}
```

### Mutex for Shared Mutable State

```kotlin
class SafeCounter {
    private val mutex = Mutex()
    private var count = 0

    suspend fun increment() {
        mutex.withLock { count++ }
    }

    suspend fun get(): Int = mutex.withLock { count }
}
```

## Exception Handling

### CoroutineExceptionHandler

```kotlin
// Install at the top-level scope for uncaught exceptions
val handler = CoroutineExceptionHandler { _, exception ->
    log.error("Uncaught coroutine exception", exception)
    metrics.increment("coroutine.uncaught_exception")
}

val scope = CoroutineScope(SupervisorJob() + Dispatchers.Default + handler)

// The handler only catches exceptions from launch, not async.
// async exceptions are delivered when you call await().
```

### Structured Error Propagation

```kotlin
sealed interface ServiceResult<out T> {
    data class Success<T>(val data: T) : ServiceResult<T>
    data class Failure(val error: ServiceError) : ServiceResult<Nothing>
}

sealed interface ServiceError {
    data class NotFound(val id: String) : ServiceError
    data class Timeout(val duration: Duration) : ServiceError
    data class Unavailable(val service: String, val cause: Throwable) : ServiceError
}

suspend fun fetchUser(id: String): ServiceResult<User> {
    return try {
        val user = withTimeout(5_000) {
            withContext(Dispatchers.IO) { userRepository.findById(id) }
        }
        if (user != null) ServiceResult.Success(user)
        else ServiceResult.Failure(ServiceError.NotFound(id))
    } catch (e: CancellationException) {
        throw e
    } catch (e: TimeoutCancellationException) {
        ServiceResult.Failure(ServiceError.Timeout(5.seconds))
    } catch (e: Exception) {
        ServiceResult.Failure(ServiceError.Unavailable("user-service", e))
    }
}
```

## Debug Tooling

```bash
# Enable coroutine debug mode for creation stack traces
java -Dkotlinx.coroutines.debug MyApp

# Coroutine names appear in thread dumps:
# "coroutine#42":StandaloneCoroutine{Active}@7c3df174

# Name coroutines for better debugging
launch(CoroutineName("order-processor")) {
    processOrders()
}
```

# DSL Patterns Reference

## Type-Safe Builders

### Basic DSL Builder

```kotlin
// The builder pattern using Kotlin's receiver lambdas
class HtmlBuilder {
    private val elements = mutableListOf<String>()

    fun head(block: HeadBuilder.() -> Unit) {
        val builder = HeadBuilder().apply(block)
        elements.add("<head>${builder.build()}</head>")
    }

    fun body(block: BodyBuilder.() -> Unit) {
        val builder = BodyBuilder().apply(block)
        elements.add("<body>${builder.build()}</body>")
    }

    fun build(): String = "<html>${elements.joinToString("\n")}</html>"
}

fun html(block: HtmlBuilder.() -> Unit): String {
    return HtmlBuilder().apply(block).build()
}

// Usage -- reads like a declarative specification
val page = html {
    head {
        title("My Page")
        meta(charset = "utf-8")
    }
    body {
        h1("Welcome")
        p("Hello, world!")
    }
}
```

### @DslMarker to Prevent Scope Leakage

Without `@DslMarker`, inner lambdas can accidentally call outer scope methods:

```kotlin
// Problem: body { } can accidentally call head { } methods
html {
    body {
        title("Oops")  // This calls HeadBuilder.title from outer scope!
    }
}

// Solution: @DslMarker restricts implicit receivers
@DslMarker
annotation class HtmlDsl

@HtmlDsl
class HtmlBuilder { /* ... */ }

@HtmlDsl
class HeadBuilder { /* ... */ }

@HtmlDsl
class BodyBuilder { /* ... */ }

// Now this is a compile error:
html {
    body {
        title("Oops")  // ERROR: 'title' is resolved to HeadBuilder
                         // which is not in the current scope
    }
}
```

## Configuration DSLs

### Server Configuration

```kotlin
@DslMarker
annotation class ServerDsl

@ServerDsl
class ServerConfig {
    var host: String = "0.0.0.0"
    var port: Int = 8080

    private var _ssl: SslConfig? = null
    private var _routes: MutableList<Route> = mutableListOf()
    private var _middleware: MutableList<Middleware> = mutableListOf()

    fun ssl(block: SslConfig.() -> Unit) {
        _ssl = SslConfig().apply(block)
    }

    fun routing(block: RoutingConfig.() -> Unit) {
        RoutingConfig(_routes).apply(block)
    }

    fun middleware(block: MiddlewareConfig.() -> Unit) {
        MiddlewareConfig(_middleware).apply(block)
    }

    fun build(): Server = Server(host, port, _ssl, _routes, _middleware)
}

@ServerDsl
class SslConfig {
    var certFile: String = ""
    var keyFile: String = ""
    var protocols: List<String> = listOf("TLSv1.3")
}

@ServerDsl
class RoutingConfig(private val routes: MutableList<Route>) {
    fun get(path: String, handler: suspend (Request) -> Response) {
        routes.add(Route("GET", path, handler))
    }

    fun post(path: String, handler: suspend (Request) -> Response) {
        routes.add(Route("POST", path, handler))
    }

    fun group(prefix: String, block: RoutingConfig.() -> Unit) {
        val nested = RoutingConfig(mutableListOf()).apply(block)
        routes.addAll(nested.routes.map { it.copy(path = "$prefix${it.path}") })
    }
}

// Usage
val server = server {
    host = "0.0.0.0"
    port = 443

    ssl {
        certFile = "/certs/server.pem"
        keyFile = "/certs/server.key"
    }

    middleware {
        cors(allowOrigin = "*")
        rateLimit(requestsPerMinute = 100)
        logging()
    }

    routing {
        get("/health") { Response.ok("healthy") }

        group("/api/v1") {
            get("/users") { req -> userController.list(req) }
            post("/users") { req -> userController.create(req) }
            get("/users/{id}") { req -> userController.get(req) }
        }
    }
}
```

## Builder Functions from stdlib

Kotlin's standard library uses this pattern extensively:

```kotlin
// buildList -- efficient list construction
val items = buildList {
    add("first")
    addAll(existingItems)
    if (includeExtra) add("extra")
}

// buildMap -- efficient map construction
val config = buildMap {
    put("host", "localhost")
    put("port", 8080)
    putAll(overrides)
}

// buildString -- efficient string construction
val csv = buildString {
    appendLine("id,name,email")
    for (user in users) {
        appendLine("${user.id},${user.name},${user.email}")
    }
}

// apply -- configure an existing object
val textView = TextView(context).apply {
    text = "Hello"
    textSize = 16f
    setTextColor(Color.BLACK)
}

// also -- side effects (logging, validation)
val user = repository.findById(id)
    .also { logger.debug("Found user: ${it?.name}") }
    ?: throw NotFoundException(id)
```

## Sealed Types as DSL Results

```kotlin
// DSL that produces a type-safe query
sealed interface QueryFilter {
    data class Equals(val field: String, val value: Any) : QueryFilter
    data class GreaterThan(val field: String, val value: Comparable<*>) : QueryFilter
    data class Contains(val field: String, val value: String) : QueryFilter
    data class And(val filters: List<QueryFilter>) : QueryFilter
    data class Or(val filters: List<QueryFilter>) : QueryFilter
}

@DslMarker
annotation class QueryDsl

@QueryDsl
class QueryBuilder {
    private val filters = mutableListOf<QueryFilter>()

    infix fun String.eq(value: Any) {
        filters.add(QueryFilter.Equals(this, value))
    }

    infix fun String.gt(value: Comparable<*>) {
        filters.add(QueryFilter.GreaterThan(this, value))
    }

    infix fun String.contains(value: String) {
        filters.add(QueryFilter.Contains(this, value))
    }

    fun or(block: QueryBuilder.() -> Unit) {
        val nested = QueryBuilder().apply(block)
        filters.add(QueryFilter.Or(nested.filters))
    }

    internal val result: QueryFilter
        get() = if (filters.size == 1) filters.first()
                else QueryFilter.And(filters)
}

fun query(block: QueryBuilder.() -> Unit): QueryFilter {
    return QueryBuilder().apply(block).result
}

// Usage
val filter = query {
    "status" eq "active"
    "age" gt 18
    or {
        "name" contains "Alice"
        "name" contains "Bob"
    }
}
```

## Value Classes for DSL Type Safety

```kotlin
@JvmInline
value class Pixels(val value: Int)

@JvmInline
value class Dp(val value: Float)

@JvmInline
value class Milliseconds(val value: Long)

// Extension properties for DSL-like syntax
val Int.px get() = Pixels(this)
val Int.dp get() = Dp(this.toFloat())
val Int.ms get() = Milliseconds(this.toLong())
val Int.seconds get() = Milliseconds(this * 1_000L)

// Usage
fun animate(duration: Milliseconds, delay: Milliseconds = 0.ms) { /* ... */ }

animate(duration = 300.ms, delay = 1.seconds)
// animate(duration = 300, delay = 1000) // Compile error -- type safety!
```

## Extension Functions as DSL Building Blocks

```kotlin
// Scoped extensions visible only in DSL context
class TestDsl {
    // These extensions only work inside TestDsl receivers
    fun String.shouldEqual(expected: String) {
        assertEquals(expected, this)
    }

    fun <T> T?.shouldNotBeNull(): T {
        assertNotNull(this)
        return this
    }

    fun <T> List<T>.shouldHaveSize(expected: Int) {
        assertEquals(expected, this.size)
    }
}

fun test(name: String, block: TestDsl.() -> Unit) {
    TestDsl().block()
}

// Usage
test("user lookup") {
    val user = repository.findById("1").shouldNotBeNull()
    user.name.shouldEqual("Alice")
    user.orders.shouldHaveSize(3)
}
```

# Java-Kotlin Interop Reference

## Calling Java from Kotlin

### Nullability of Java Types

Java types without nullability annotations are **platform types** in Kotlin, denoted as `Type!`. They can be treated as either nullable or non-nullable, but incorrect assumptions crash at runtime.

```kotlin
// Java code
public class UserRepository {
    public User findById(String id) { ... }  // May return null
    public List<User> findAll() { ... }      // May return null list
}

// Kotlin: platform types are dangerous
val user = repository.findById("1")  // Type is User! (platform type)
user.name  // Compiles, but NPE if user is null

// SAFE: treat as nullable until proven otherwise
val user: User? = repository.findById("1")
val name = user?.name ?: "Unknown"

// BEST: add @Nullable/@NonNull to the Java code
// Java:
@Nullable public User findById(String id) { ... }
@NonNull public List<User> findAll() { ... }
```

### Annotations That Kotlin Recognizes

| Annotation Source | @Nullable | @NonNull |
| --- | --- | --- |
| JSpecify | `@Nullable` | `@NonNull` |
| JetBrains | `@Nullable` | `@NotNull` |
| JSR-305 | `@Nullable` | `@Nonnull` |
| Android | `@Nullable` | `@NonNull` |
| Eclipse | `@Nullable` | `@NonNull` |

**Recommendation**: Use JSpecify annotations (`org.jspecify:jspecify`) as they are becoming the standard.

### Java Collections in Kotlin

```kotlin
// Java collections are mutable in Kotlin
val javaList: MutableList<String> = JavaClass.getNames()  // MutableList
val kotlinList: List<String> = javaList  // Upcast to read-only view
// But javaList and kotlinList share the same backing list!
// Mutations via javaList are visible through kotlinList.

// SAFE: copy if immutability is required
val safeCopy: List<String> = javaList.toList()
```

### SAM Conversions (Java Functional Interfaces)

```kotlin
// Java
public interface Callback<T> {
    void onResult(T result);
}

public void fetchAsync(Callback<User> callback) { ... }

// Kotlin: SAM conversion -- lambda instead of anonymous class
service.fetchAsync { user ->
    println(user.name)
}

// Kotlin: explicit SAM constructor (when ambiguous)
service.fetchAsync(Callback { user ->
    println(user.name)
})
```

## Calling Kotlin from Java

### @JvmStatic for Companion Object Methods

```kotlin
class UserValidator {
    companion object {
        @JvmStatic
        fun isValid(email: String): Boolean = email.contains("@")

        // Without @JvmStatic:
        // Java: UserValidator.Companion.isValid(email) -- awkward
        // With @JvmStatic:
        // Java: UserValidator.isValid(email) -- natural
    }
}
```

### @JvmField for Direct Field Access

```kotlin
class Config {
    @JvmField val maxRetries = 3
    // Without @JvmField: Java calls config.getMaxRetries()
    // With @JvmField: Java calls config.maxRetries (direct field access)
}

// Most useful for constants
object Constants {
    @JvmField val MAX_CONNECTIONS = 100
    // Java: Constants.MAX_CONNECTIONS (no getter)
}
```

### @JvmOverloads for Default Parameters

```kotlin
class HttpClient {
    @JvmOverloads
    fun request(
        url: String,
        method: String = "GET",
        headers: Map<String, String> = emptyMap(),
        timeout: Long = 5000,
    ): Response { ... }
}

// Java can now call:
// client.request("https://api.example.com")
// client.request("https://api.example.com", "POST")
// client.request("https://api.example.com", "POST", headers)
// Without @JvmOverloads, Java must pass ALL parameters
```

### @JvmName for Name Conflicts

```kotlin
// Kotlin allows overloading by return type (via name mangling)
// but Java does not. Use @JvmName to avoid conflicts.

@JvmName("getStringUsers")
fun getUsers(): List<String> = listOf("Alice", "Bob")

@JvmName("getUserObjects")
fun getUsers(): List<User> = listOf(User("Alice"), User("Bob"))
```

### Exposing Kotlin Extension Functions to Java

```kotlin
// Extension function
fun String.toSlug(): String = this.lowercase().replace(" ", "-")

// Generated Java signature:
// public static String toSlug(String receiver)
// Java: StringExtensionsKt.toSlug("Hello World")

// Use @JvmName on the file to change the generated class name
@file:JvmName("StringUtils")
package com.example.util

fun String.toSlug(): String = this.lowercase().replace(" ", "-")
// Java: StringUtils.toSlug("Hello World")
```

## Migration Patterns

### Gradual Java-to-Kotlin Migration

1. **Start with data classes**: Convert Java POJOs/DTOs to Kotlin data classes first. They have no behavior, so risk is low.

2. **Convert utility classes**: Static utility methods become top-level functions or extension functions.

3. **Convert tests**: Kotlin tests are often half the lines. JUnit 5 works identically.

4. **Convert services last**: These have the most behavior and integration points.

```kotlin
// Step 1: Java DTO -> Kotlin data class
// Before (Java, ~60 lines with equals/hashCode/toString)
public class UserDto {
    private final String id;
    private final String name;
    // ... constructor, getters, equals, hashCode, toString
}

// After (Kotlin, 1 line)
data class UserDto(val id: String, val name: String)
```

### Annotation Processing (kapt vs KSP)

```kotlin
// kapt (Kotlin Annotation Processing Tool) -- wraps Java annotation processors
// Slower because it generates Java stubs first
plugins {
    kotlin("kapt")
}
dependencies {
    kapt("com.google.dagger:dagger-compiler:2.51")
}

// KSP (Kotlin Symbol Processing) -- native Kotlin processing
// 2x faster than kapt, direct Kotlin AST access
plugins {
    id("com.google.devtools.ksp") version "2.1.0-1.0.29"
}
dependencies {
    ksp("io.insert-koin:koin-ksp-compiler:1.4.0")
}

// Migration: prefer KSP when the library supports it
// Libraries with KSP support: Room, Moshi, Koin, Hilt (experimental)
// Libraries requiring kapt: Dagger (classic), some legacy processors
```

### Build Configuration for Mixed Projects

```kotlin
// build.gradle.kts for a project with both Java and Kotlin
plugins {
    kotlin("jvm") version "2.1.0"
    java
}

kotlin {
    jvmToolchain(21)

    compilerOptions {
        jvmTarget = JvmTarget.JVM_21
        freeCompilerArgs.addAll(
            "-Xjvm-default=all",     // Generate default methods in interfaces
            "-opt-in=kotlin.RequiresOptIn",
        )
    }
}

java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(21)
    }
}

// Source layout: Java and Kotlin sources can coexist
// src/main/java/   -- Java files
// src/main/kotlin/ -- Kotlin files
// Both are compiled together with cross-references working
```

## Common Interop Pitfalls

| Issue | Cause | Fix |
| --- | --- | --- |
| NPE from Java return | Platform types treated as non-null | Annotate Java with `@Nullable` or treat as `Type?` in Kotlin |
| `UnsupportedOperationException` from `List.add()` | Kotlin's `listOf()` returns unmodifiable list | Use `mutableListOf()` or `ArrayList()` when Java callers need mutability |
| `NoSuchMethodError` at runtime | Kotlin inline class erased to primitive | Add `@JvmInline` and check generated bytecode |
| Cannot access Kotlin `internal` from Java | `internal` becomes `public` in bytecode (mangled name) | Use `@JvmName` or restructure visibility |
| Java cannot call Kotlin default parameters | Java does not support default values | Add `@JvmOverloads` to the Kotlin function |
| Coroutines not callable from Java | `suspend` functions have a `Continuation` parameter | Wrap in a non-suspend function returning `CompletableFuture` |

### Exposing Coroutines to Java

```kotlin
// Kotlin coroutine
suspend fun getUser(id: String): User { ... }

// Java-friendly wrapper
fun getUserFuture(id: String): CompletableFuture<User> {
    return scope.future { getUser(id) }
}

// Or using kotlinx-coroutines-jdk8
import kotlinx.coroutines.future.future

fun getUserFuture(id: String): CompletableFuture<User> =
    scope.future { getUser(id) }
```

# Kotlin Multiplatform Reference

## Project Structure

### Source Set Layout

```
shared/
  src/
    commonMain/     # Shared code (pure Kotlin, no platform APIs)
    commonTest/     # Shared tests
    androidMain/    # Android-specific implementations
    androidTest/    # Android-specific tests (instrumented or unit)
    iosMain/        # iOS-specific implementations (Kotlin/Native)
    iosTest/        # iOS-specific tests
    jvmMain/        # JVM server-specific implementations
    jvmTest/        # JVM server-specific tests
    jsMain/         # JavaScript target (browser or Node.js)
    wasmJsMain/     # Wasm target for browsers
```

### build.gradle.kts

```kotlin
plugins {
    kotlin("multiplatform") version "2.1.0"
    kotlin("plugin.serialization") version "2.1.0"
    id("com.android.library")
}

kotlin {
    // Targets
    androidTarget()

    listOf(iosX64(), iosArm64(), iosSimulatorArm64()).forEach {
        it.binaries.framework {
            baseName = "shared"
            isStatic = true  // Static framework for easier CocoaPods integration
        }
    }

    jvm()

    // Source sets
    sourceSets {
        commonMain.dependencies {
            implementation("org.jetbrains.kotlinx:kotlinx-coroutines-core:1.9.0")
            implementation("org.jetbrains.kotlinx:kotlinx-serialization-json:1.7.3")
            implementation("org.jetbrains.kotlinx:kotlinx-datetime:0.6.1")
            implementation("io.ktor:ktor-client-core:3.0.2")
        }

        commonTest.dependencies {
            implementation(kotlin("test"))
            implementation("org.jetbrains.kotlinx:kotlinx-coroutines-test:1.9.0")
            implementation("app.cash.turbine:turbine:1.2.0")
        }

        androidMain.dependencies {
            implementation("io.ktor:ktor-client-okhttp:3.0.2")
        }

        iosMain.dependencies {
            implementation("io.ktor:ktor-client-darwin:3.0.2")
        }

        jvmMain.dependencies {
            implementation("io.ktor:ktor-client-java:3.0.2")
        }
    }
}
```

## expect/actual Pattern

### When to Use expect/actual

Use `expect`/`actual` for functionality that genuinely differs across platforms. Common cases:
- Logging (Android Log, iOS NSLog, JVM SLF4J)
- File system access
- Platform-specific crypto
- UUID generation
- Date/time formatting with locale

### Declaration Rules

```kotlin
// commonMain: expect declaration (no body)
expect fun platformName(): String

expect class PlatformLogger(tag: String) {
    fun debug(message: String)
    fun error(message: String, throwable: Throwable? = null)
}

// androidMain: actual implementation
actual fun platformName(): String = "Android ${Build.VERSION.SDK_INT}"

actual class PlatformLogger actual constructor(private val tag: String) {
    actual fun debug(message: String) = Log.d(tag, message)
    actual fun error(message: String, throwable: Throwable?) {
        Log.e(tag, message, throwable)
    }
}

// iosMain: actual implementation
actual fun platformName(): String = UIDevice.currentDevice.systemName()

actual class PlatformLogger actual constructor(private val tag: String) {
    actual fun debug(message: String) = NSLog("[$tag] $message")
    actual fun error(message: String, throwable: Throwable?) {
        NSLog("[$tag] ERROR: $message ${throwable?.message ?: ""}")
    }
}
```

### Prefer Interfaces Over expect/actual When Possible

```kotlin
// BETTER: interface in commonMain with platform-injected implementations
// This is more testable and does not require compiler-level linking

// commonMain
interface Logger {
    fun debug(message: String)
    fun error(message: String, throwable: Throwable? = null)
}

// androidMain
class AndroidLogger(private val tag: String) : Logger {
    override fun debug(message: String) = Log.d(tag, message)
    override fun error(message: String, throwable: Throwable?) = Log.e(tag, message, throwable)
}

// Injected via constructor or DI framework
class UserRepository(private val logger: Logger) {
    // testable with a FakeLogger
}
```

